+/*
+  목업 '글 끝'의 완료 카드(.done-card)를 글자만으로 따른다. 단계 색 빛과 그림 장면은 B13(T193)이 더한다.
+  초록 테두리와 옅은 고리는 '방금 끝낸 것'을 보이는 카드에만 쓴다.
+*/
+.card {
+  position: relative;
+  overflow: hidden;
+  border: 1px solid color-mix(in srgb, var(--thorp-accent) 35%, transparent);
+  border-radius: var(--thorp-radius-card, 16px);
+  background: var(--thorp-surface);
+  box-shadow:
+    0 0 0 6px color-mix(in srgb, var(--thorp-accent) 6%, transparent),
+    0 30px 60px -36px rgb(0 0 0 / 90%);
+}
+
+/* 구역 사이를 가는 줄로 나눈다(목업 .dc-sec). */
+.section {
+  padding: 22px 28px;
+  border-top: 1px solid var(--thorp-line);
+}
+
+.section:first-child {
+  border-top: 0;
+}
+
+/* 머리: 제목인 완료 날짜(작게) 아래에 단계 진행(크게). 보이는 순서가 읽는 순서다(목업 .dc-head). */
+.head {
+  display: flex;
+  flex-direction: column;
+  align-items: flex-start;
+  gap: 4px;
+}
+
+.date {
+  margin: 0;
+  color: var(--thorp-copy);
+  font-size: var(--thorp-text-body, 0.9rem);
+  font-weight: 650;
+  letter-spacing: 0;
+}
+
+.progress {
+  margin: 0;
+  color: var(--thorp-foreground);
+  font-family: var(--thorp-font-number, inherit);
+  font-size: 1.75rem;
+  font-weight: 800;
+  letter-spacing: -0.02em;
+  line-height: 1.1;
+}
+
+/* 이번에 얻은 것: 새 배지 | 레벨 | 받은 경험치(목업 .dc-ach). 칸 사이는 세로 줄이다. */
+.achievements {
+  display: flex;
+  flex-wrap: wrap;
+  row-gap: 16px;
+}
+
+.column {
+  display: flex;
+  flex: 1 1 0;
+  flex-direction: column;
+  align-items: center;
+  min-width: 0;
+  padding: 0 20px;
+  border-left: 1px solid var(--thorp-line);
+  text-align: center;
+}
+
+.column:first-child {
+  padding-left: 0;
+  border-left: 0;
+}
+
+.expColumn {
+  flex: 0 0 220px;
+  align-items: stretch;
+  padding-right: 0;
+  text-align: left;
+}
+
+.expColumn:only-child {
+  flex: 1 1 auto;
+  max-width: 320px;
+}
+
+.label {
+  align-self: stretch;
+  margin-bottom: 10px;
+  color: var(--thorp-muted);
+  font-size: var(--thorp-text-small, 0.8rem);
+  font-weight: 650;
+}
+
+.gainedItem + .gainedItem {
+  margin-top: 14px;
+}
+
+.big {
+  display: block;
+  font-size: 1.375rem;
+  font-weight: 800;
+  letter-spacing: -0.01em;
+  line-height: 1.25;
+}
+
+.received {
+  display: flex;
+  flex-wrap: wrap;
+  justify-content: center;
+  align-items: center;
+  gap: 6px;
+  margin-top: 8px;
+}
+
+/* '받음 날짜'(목업 .chip.got). 테두리 없는 초록 채움이다. */
+.chip {
+  display: inline-flex;
+  align-items: center;
+  height: 24px;
+  padding: 0 9px;
+  border-radius: 999px;
+  background: var(--thorp-accent-muted);
+  color: var(--thorp-accent-soft);
+  font-size: var(--thorp-text-small, 0.8rem);
+  font-weight: 650;
+  white-space: nowrap;
+}
+
+/* '새' 알약(목업 .pill-new). 'NEW'를 쓰지 않는다(design-notes §4). */
+.newPill {
+  display: inline-flex;
+  align-items: center;
+  height: 20px;
+  padding: 0 8px;
+  border-radius: 999px;
+  background: var(--thorp-accent-muted);
+  box-shadow: inset 0 0 0 1px var(--thorp-accent-soft);
+  color: var(--thorp-accent-soft);
+  font-size: var(--thorp-text-caption, 0.75rem);
+  font-weight: 700;
+  white-space: nowrap;
+}
+
+.exp {
+  margin: 0;
+  padding: 0;
+  list-style: none;
+}
+
+.exp li {
+  display: flex;
+  justify-content: space-between;
+  align-items: baseline;
+  gap: 10px;
+  padding: 3px 0;
+  color: var(--thorp-copy);
+  font-size: var(--thorp-text-body, 0.9rem);
+}
+
+.points {
+  color: var(--thorp-foreground);
+  font-family: var(--thorp-font-number, inherit);
+  font-variant-numeric: tabular-nums;
+  font-weight: 700;
+}
+
+.exp .sum {
+  margin-top: 6px;
+  padding-top: 8px;
+  border-top: 1px solid var(--thorp-line-strong);
+  color: var(--thorp-foreground);
+  font-weight: 700;
+}
+
+.exp .sum .points {
+  font-size: 1.125rem;
+}
+
+/* 상태 문장(목업 .status). 보이는 글자이고 알림 영역은 글 끝이 따로 둔다. */
+.status {
+  display: flex;
+  align-items: flex-start;
+  gap: 10px;
+  margin: 20px 0 0;
+  padding: 12px 14px;
+  border-radius: var(--thorp-radius-inset, 10px);
+  background: rgb(255 255 255 / 2.5%);
+  color: var(--thorp-copy);
+  font-size: 0.95rem;
+  line-height: 1.6;
+}
+
+.status svg {
+  flex: none;
+  margin-top: 4px;
+}
+
+.statusHalo {
+  fill: color-mix(in srgb, var(--thorp-accent-soft) 18%, transparent);
+}
+
+.statusDot {
+  fill: var(--thorp-accent-soft);
+}
+
+.terms {
+  display: flex;
+  flex-wrap: wrap;
+  align-items: center;
+  gap: 10px;
+  color: var(--thorp-copy);
+  font-size: var(--thorp-text-body, 0.9rem);
+}
+
+.termList {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 8px;
+  margin: 0;
+  padding: 0;
+  list-style: none;
+}
+
+/* 익힐 용어 알약(목업 .tpill). 초록 1.5px 안쪽 선이다. */
+.term {
+  display: inline-flex;
+  align-items: center;
+  gap: 6px;
+  height: 30px;
+  padding: 0 12px;
+  border-radius: 999px;
+  box-shadow: inset 0 0 0 1.5px var(--thorp-accent-soft);
+  color: var(--thorp-foreground);
+  font-size: var(--thorp-text-body, 0.9rem);
+  font-weight: 650;
+  white-space: nowrap;
+}
+
+.mastered {
+  color: var(--thorp-accent-soft);
+  font-style: normal;
+}
+
+/* 다음 글·이어서 읽기 카드(목업 .nextc). 단계 색 띠와 풍경 그림은 계약 `next`에 단계가 없어 두지 않는다. */
+.nextLink {
+  display: grid;
+  grid-template-columns: minmax(0, 1fr) 24px;
+  align-items: center;
+  gap: 16px;
+  min-height: 44px;
+  padding: 16px 18px 16px 20px;
+  border-radius: var(--thorp-radius-inset, 12px);
+  background: var(--thorp-surface-raised);
+  box-shadow: inset 0 0 0 1px var(--thorp-line);
+  color: var(--thorp-foreground);
+  text-decoration: none;
+}
+
+.nextText {
+  display: grid;
+  gap: 2px;
+  min-width: 0;
+}
+
+.nextLabel {
+  color: var(--thorp-copy);
+  font-size: var(--thorp-text-small, 0.8rem);
+  font-weight: 650;
+}
+
+.nextTitle {
+  font-size: 1.25rem;
+  font-weight: 700;
+  letter-spacing: -0.01em;
+}
+
+.nextNumber {
+  margin-right: 8px;
+  color: var(--thorp-muted);
+  font-family: var(--thorp-font-number, inherit);
+  font-size: var(--thorp-text-body, 0.9rem);
+  font-weight: 700;
+}
+
+.nextArrow {
+  color: var(--thorp-copy);
+}
+
+.nextLink:hover .nextTitle {
+  color: var(--thorp-accent-soft);
+}
+
+.nextLink:focus-visible {
+  outline: var(--thorp-focus-outline-compact);
+  outline-offset: var(--thorp-focus-offset-compact);
+}
+
+.allDone {
+  margin: 0;
+  color: var(--thorp-copy);
+}
+
+/* 좁은 화면(목업 720px 미만): 새 배지와 레벨을 한 줄에 나란히, 받은 경험치는 그 아래 전체 폭이다. */
+@media (max-width: 719px) {
+  .section {
+    padding: 18px 16px;
+  }
+
+  .column {
+    padding: 0 8px;
+  }
+
+  .column:first-child {
+    padding-left: 0;
+  }
+
+  .expColumn {
+    flex: 1 1 100%;
+    max-width: none;
+    padding: 16px 0 0;
+    border-top: 1px solid var(--thorp-line);
+    border-left: 0;
+  }
+
+  .expColumn:only-child {
+    padding-top: 0;
+    border-top: 0;
+  }
+
+  .big {
+    font-size: 1.125rem;
+  }
+
+  .nextLink {
+    grid-template-columns: minmax(0, 1fr) 20px;
+    gap: 12px;
+    padding: 14px 14px 14px 16px;
+  }
+
+  .nextTitle {
+    font-size: 1.0625rem;
+  }
+}

